//! The standard function `run_background` (ADR-046 decision 3).
//!
//! In every schema (ADR-024), but **linked by use** (ADR-052): its dispatcher is written here by
//! hand rather than generated by `#[undra::api]`, so that a core with no background task answers
//! an idle report synchronously and links neither the run nor an asynchronous call for it; the
//! asynchronous run is reached only through `Runtime::add_background_task`
//! ([`Runtime::background_call`](undra_runtime::Runtime::background_call)). The declaration below
//! is the one the macro produced (name, id, parameter, return type, `async`, docs), so the schema
//! and its hash are unchanged (`tests/schema.rs` pins the standard surface's hash).

use core::any::Any;
use std::time::Duration;

use undra_runtime::background::BackgroundTotals;
use undra_runtime::{Ctx, DispatchResult, Runtime};
use undra_wire::{Decode, Reader};

use crate::BackgroundReport;
use crate::root::meta::{
    DispatchCall, DispatchOutcome, FunctionMeta, ParamMeta, Registration, TypeRefMeta, ids,
};

/// Runs the background tasks for at most `deadline_ms` (the window the OS granted).
// What it does, in full (ADR-046): every background task of the runtime starts at once (the
// offline queue's replay, the refetch of stale queries and the flush of what waits to be persisted,
// `undra-query`'s; the app's own). The call returns when they are all done, or half a second before
// the deadline so the host can still tell the OS it finished, with what got done and what is left.
// A host about to lose its window cancels the call; work already done is kept. (The schema's docs
// are the first line only: a core embeds its schema's docs, ADR-050, and every core has this.)
pub async fn run_background(ctx: &Ctx, deadline_ms: u64) -> BackgroundReport {
    // A core that registered no background task has no runner linked (ADR-052): nothing to do.
    let totals = match ctx.runtime().background_runner() {
        Some(run) => run(ctx, Duration::from_millis(deadline_ms)).await,
        None => BackgroundTotals::IDLE,
    };
    BackgroundReport {
        finished: totals.finished,
        replayed: totals.replayed,
        refetched: totals.refetched,
        still_pending: totals.still_pending,
    }
}

/// The dispatcher of `run_background`: decodes `deadline_ms` and asks the runtime, which answers
/// at once when it has no background task.
fn dispatch(runtime: &dyn Any, call: DispatchCall<'_>) -> DispatchOutcome {
    let result = match runtime.downcast_ref::<Runtime>() {
        Some(runtime) if call.method_id == ids::function_id("run_background") => {
            let mut r = Reader::new(call.args);
            match u64::decode(&mut r).and_then(|deadline_ms| r.finish().map(|()| deadline_ms)) {
                Ok(deadline_ms) => runtime.background_call(deadline_ms),
                Err(e) => DispatchResult::BadRequest(format!(
                    "cannot decode the arguments of `run_background`: {e}"
                )),
            }
        }
        _ => DispatchResult::Unknown,
    };
    DispatchOutcome::new(result)
}

/// The declaration of `run_background`, as `#[undra::api]` writes it for an `async fn(ctx: &Ctx,
/// deadline_ms: u64) -> BackgroundReport`.
static META: FunctionMeta = FunctionMeta {
    name: "run_background",
    method_id: ids::function_id("run_background"),
    params: &[ParamMeta {
        name: "deadline_ms",
        ty: TypeRefMeta::U64,
    }],
    returns: TypeRefMeta::Named("BackgroundReport"),
    is_async: true,
    takes_ctx: true,
    docs: "Runs the background tasks for at most `deadline_ms` (the window the OS granted).",
    dispatch,
};

undra_meta::inventory::submit! {
    Registration::Function(&META)
}
